import{at as e,it as t,n,vt as r}from"./chunks/framework.DeZaKrRW.js";var i=JSON.parse(`{"title":"嵌套实测 B：srcDir 下的 public 目录迁移陷阱","description":"","frontmatter":{"title":"嵌套实测 B：srcDir 下的 public 目录迁移陷阱"},"headers":[],"relativePath":"04-directory/nested/public-trap.md","filePath":"04-directory/nested/02-public-trap.md"}`),a={name:`04-directory/nested/public-trap.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,i[0]||=[e(`<h1 id="嵌套实测-b-srcdir-下的-public-目录迁移陷阱" tabindex="-1">嵌套实测 B：<code>srcDir</code> 下的 <code>public</code> 目录迁移陷阱 <a class="header-anchor" href="#嵌套实测-b-srcdir-下的-public-目录迁移陷阱" aria-label="Permalink to “嵌套实测 B：srcDir 下的 public 目录迁移陷阱”">​</a></h1><p>在 Astro 等前端框架中，无论页面放在 <code>src/</code> 哪一层，静态资源始终固定在仓库根目录 <code>public/</code>；但在 VitePress 中，一旦设置 <code>srcDir: &#39;docs&#39;</code>：</p><ul><li><p>根路径静态目录会变成 <strong><code>docs/public/</code></strong>（而 <code>.vitepress/</code> 配置目录却依然留在仓库根目录 <code>.vitepress/</code>，或也可放进 <code>docs/.vitepress/</code>）。</p></li><li><p>这种“配置可在外、静态资源必须在内”的不对称约定，极易导致开发者把 <code>.nojekyll</code> 或图标放错位置。</p></li><li><p><a href="./../">返回《04. 目录结构与路由取舍》</a></p></li></ul>`,3)])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};